161	     * Increases the age of the organism by one. If it goes over the max age, the organism dies.
162	     */
163	    protected void incrementAge()
164	    {
165	        age++;
166	        if (age > attributes.getMaxAge())
167	        {
168	            setDead();
169	        }
170	    }
