172	    /**
173	     * Indicate that the organism is no longer alive.
174	     * It is removed from the field.
175	     */
176	    protected void setDead()
177	    {
178	        alive = false;
179	        if(location != null) {
180	            field.clear(location);
181	            location = null;
182	            field = null;
183	        }
184	    }
