186	    /**
187	     * Place the organism at the new location in the given field.
188	     * @param newLocation The organism's new location.
189	     */
190	    protected void setLocation(Location newLocation)
191	    {
192	        if(location != null) {
193	            field.clear(location);
194	        }
195	        location = newLocation;
196	        field.place(this, newLocation);
197	    }
