207	    /**
208	     * Move the organism if its species requires relocation this step.
209	     */
210	    protected void relocate()
211	    {
212	        RelocationStrategy relocationStrategy = attributes.getRelocationStrategy();
213	        Location newLocation = relocationStrategy.findNextLocation(this);
214	        if(newLocation != null) {
215	            setLocation(newLocation);
216	        }
217	        else if(relocationStrategy.diesWhenBlocked()) {
218	            setDead();
219	        }
220	    }
